    ('LIQUIDITY_AND_TENOR', 'COMMITTED_FACILITY', 4),
    ('LIQUIDITY_AND_TENOR', 'EXTEND_FACILITY_TENORS', 5),
    ('LIQUIDITY_AND_TENOR', 'REPLACE_MARGINS_WITH_LIMITS', 6),
    ('WORKING_CAPITAL_RELEASE', 'COLLECT_OVERDUE_AR', 1),
    ('WORKING_CAPITAL_RELEASE', 'RELEASE_RETENTIONS', 2),
    ('WORKING_CAPITAL_RELEASE', 'LIQUIDATE_SLOW_STOCK', 3),
    ('WORKING_CAPITAL_RELEASE', 'FACTOR_WITHOUT_RECOURSE', 4),
    ('WORKING_CAPITAL_RELEASE', 'PAY_OVERDUE_SUPPLIERS', 5),
    ('DELEVERAGING', 'SELL_NON_OPERATING_ASSETS', 1),
    ('DELEVERAGING', 'APPLY_MARGINS_TO_DEBT', 2),
    ('DELEVERAGING', 'SETTLE_RELATED_RECEIVABLES', 3),
    ('DELEVERAGING', 'REPAY_SHAREHOLDER_LOANS', 4),
    ('DELEVERAGING', 'FACTOR_WITHOUT_RECOURSE', 5),
