    ('RELATED_PARTY_CLEANUP', 'CONVERT_DUE_TO_RELATED_TO_SUB', 6),
    ('ASSET_QUALITY_CLEANUP', 'PROVIDE_AND_ENFORCE_OLD_AR', 1),
    ('ASSET_QUALITY_CLEANUP', 'LIQUIDATE_SLOW_STOCK', 2),
    ('ASSET_QUALITY_CLEANUP', 'COLLECT_OVERDUE_AR', 3),
    ('RISK_HEDGING', 'FX_HEDGE', 1),
    ('RISK_HEDGING', 'RATE_HEDGE', 2)
            ) AS v (PlanCode, RemedyCode, SortOrder)
       JOIN fin.StrengtheningPlan AS p ON p.Code = v.PlanCode
       JOIN fin.CreditRemedy AS r ON r.Code = v.RemedyCode) AS s
   ON d.PlanId = s.PlanId AND d.RemedyId = s.RemedyId
WHEN NOT MATCHED THEN
    INSERT (PlanId, RemedyId, SortOrder) VALUES (s.PlanId, s.RemedyId, s.SortOrder);
GO
MERGE fin.CreditText AS d
USING (VALUES
    ('RECLASS', 'ADJ_IMPAIRMENTS', N'إضافة الهبوط في القيمة إلى EBITDA', N'Impairments added back to EBITDA',
