    ('FX_EXPOSURE_TO_TNW', 'DERIVATIVES_NOTIONAL', 5, 10, 20, 35, 0, 126),
    ('PRODUCT_CASH_FLOW_QUALITY', 'REVENUE', 2, 2.75, 3.5, 4.25, 0, 127),
    ('PRODUCT_CONCENTRATION', 'REVENUE', 40, 60, 75, 90, 0, 128),
    ('INVENTORY_CRISIS_VALUE', 'INVENTORY', 75, 60, 45, 30, 1, 129),
    ('INVENTORY_DAYS_TO_SELL_STAGNANT', 'INVENTORY', 90, 150, 240, 365, 0, 130),
