MERGE fin.ScorecardSubfactor AS d
USING (SELECT sc.ScorecardId, m.CreditMetricId AS MetricId, v.Code, v.NameAr, v.NameEn, v.GuideAr, v.SortOrder
       FROM (VALUES
    ('BUSINESS_PROFILE', 'CONTRACT_BASE', N'قاعدة العقود', N'Contract base',
     N'Aa: أكثر من 70% من الإيرادات بعقود تتجاوز 3 سنوات مع حد أدنى مضمون أو بند تعديل للوقود | A: 50–70% بعقود 2–3 سنوات | Baa: 30–50% بعقود سنوية والباقي فوري | Ba: 15–30% بعقود، والغالب أسعار فورية | B: أقل من 15% بعقود، وإيرادات فورية بالكامل تقريبًا', 1),
    ('BUSINESS_PROFILE', 'CUSTOMER_CONCENTRATION', N'تركّز العملاء', N'Customer concentration',
     N'Aa: أكبر عميل دون 5% وأكبر خمسة دون 20% | A: أكبر عميل دون 10% وأكبر خمسة دون 35% | Baa: أكبر عميل 10–20% أو أكبر خمسة 35–55% | Ba: أكبر عميل 20–40% أو أكبر خمسة 55–75% | B: عميل واحد فوق 40% من الإيرادات أو طرف ذو علاقة', 2),
    ('BUSINESS_PROFILE', 'FLEET_AGE_OWNERSHIP', N'عمر الأسطول وملكيته', N'Fleet age and ownership',
     N'Aa: متوسط عمر الشاحنات دون 4 سنوات (والسفن دون 8)، وأكثر من 70% مملوك غير مرهون، وصيانة داخلية | A: عمر 4–6 سنوات (سفن 8–12)، وغالبه مملوك | Baa: عمر 6–9 سنوات (سفن 12–16)، ومزيج ملكية وتأجير | Ba: عمر 9–12 سنة (سفن 16–20)، أو تأجير قصير لأكثر من نصف الأسطول | B: عمر فوق 12 سنة (سفن فوق 20)، أو أسطول مرهون بالكامل بحاجة إلى إحلال عاجل', 3),
    ('BUSINESS_PROFILE', 'NETWORK_INFRASTRUCTURE', N'الشبكة والبنية التحتية والامتيازات', N'Network, infrastructure and concessions',
     N'Aa: أصول استراتيجية (امتيازات موانئ، مستودعات جمركية، محطات) بمدد تفوق 15 سنة وتغطية ثلاث دول أو أكثر | A: مستودعات ومراكز توزيع مملوكة في عدة مدن، وامتيازات 10–15 سنة | Baa: مستودعات مستأجرة وشبكة وطنية بلا امتيازات | Ba: تغطية محدودة لمدينة أو ممر واحد | B: لا بنية تحتية خاصة، ومسار أو ميناء واحد معرض للإغلاق', 4),
    ('BUSINESS_PROFILE', 'COST_PASSTHROUGH', N'تمرير تكاليف الوقود والتشغيل', N'Fuel and operating cost pass-through',
     N'Aa: بنود تعديل الوقود تغطي أكثر من 90% من تغيرات الوقود خلال شهر | A: تغطية 70–90% بتأخير حتى ربع سنة | Baa: تمرير جزئي 40–70% بتأخير 3–6 أشهر | Ba: إعادة تفاوض متفرقة، وتمرير دون 40% | B: عقود بأسعار ثابتة بلا تمرير لتكاليف الوقود والأجور', 5),
    ('BUSINESS_PROFILE', 'SERVICE_DIVERSIFICATION', N'تنوع الخدمات والقطاعات المخدومة', N'Service and end-market diversification',
     N'Aa: عدة خدمات (نقل بري، لوجستيات تعاقدية، شحن، تخزين) وقطاعات (سلع استهلاكية، نفط وغاز، صناعة، حكومة) لا يتجاوز أي منها 30% | A: ثلاث خدمات أو قطاعات، وأكبرها دون 45% | Baa: خدمتان رئيسيتان، وأكبر قطاع 45–60% | Ba: خدمة واحدة أو قطاع واحد (مثل البناء أو النفط) فوق 60% | B: خدمة واحدة لقطاع أو مشروع واحد', 6),
    ('FINANCIAL_POLICY', 'DISTRIBUTION_POLICY', N'سياسة التوزيعات والمسحوبات', N'Dividend and drawings policy',
     N'Aa: توزيعات مقيدة بسياسة مكتوبة دون 30% من الربح ولا مسحوبات | A: توزيعات دون 50% من الربح ولا تتجاوز التدفق الحر | Baa: توزيعات أو مسحوبات تقارب الربح في السنوات الجيدة | Ba: مسحوبات تتجاوز الربح أحيانًا أو تُمول بالدين | B: مسحوبات منتظمة تفوق الربح، وحسابات جارية مدينة للشركاء', 1),
    ('FINANCIAL_POLICY', 'LEVERAGE_TARGET', N'سياسة الرفع والتمويل', N'Leverage and funding policy',
     N'Aa: سقف رفع معلن ومحترم، وتمويل الأصول الطويلة بتمويل طويل | A: رفع معتدل مستهدف وآجال تمويل متوافقة مع الأصول | Baa: لا سقف معلن، ورفع يرتفع مع النمو ثم ينخفض | Ba: نمو أو استحواذات ممولة بدين قصير الأجل | B: رفع متصاعد بلا خطة، وتمويل أصول طويلة بخطوط قصيرة', 2),
    ('FINANCIAL_POLICY', 'RELATED_PARTY_GOVERNANCE', N'حوكمة تعاملات الأطراف ذات العلاقة', N'Related-party governance',
     N'Aa: تعاملات محدودة بشروط السوق ويعتمدها مجلس أو لجنة مستقلة | A: تعاملات تجارية موثقة بعقود وأسعار السوق | Baa: أرصدة متبادلة مع شركات الشركاء دون إطار مكتوب | Ba: أرصدة مدينة كبيرة على الشركاء أو الشقيقات دون جدول سداد | B: تحويلات متكررة للشركاء أو كفالات لشقيقات متعثرة', 3),
    ('FINANCIAL_POLICY', 'DISCLOSURE_TIMELINESS', N'الإفصاح وتوقيت القوائم', N'Disclosure and timeliness',
     N'Aa: قوائم مدققة من مكتب كبير خلال 90 يومًا، وقوائم ربعية، وإفصاح كامل | A: قوائم مدققة خلال 120 يومًا وإفصاحات المعايير كاملة | Baa: قوائم مدققة خلال ستة أشهر وإفصاح عادي | Ba: تأخر في القوائم أو تحفظ سابق أو إفصاح ناقص عن الأعمار والضمانات | B: قوائم إدارية فقط أو تحفظ جوهري أو تغيير متكرر للمراجع', 4),
    ('FINANCIAL_POLICY', 'BANKING_TRACK_RECORD', N'السجل مع البنوك', N'Banking track record',
     N'Aa: لا تأخر ولا خرق في عشر سنوات، وعلاقات مع عدة بنوك | A: لا تأخر، وخرق فني نادر عولج بسرعة | Baa: تأخر فني محدود أو تنازل واحد عن تعهد | Ba: إعادة جدولة سابقة أو تنازلات متكررة | B: تعثر أو إعادة هيكلة قائمة أو قضايا تنفيذ', 5)
            ) AS v (MetricCode, Code, NameAr, NameEn, GuideAr, SortOrder)
       JOIN fin.Scorecard AS sc ON sc.Code = 'TRANSPORT_LOGISTICS' AND sc.VersionNo = 1 AND sc.Status = 'DRAFT'
       JOIN fin.CreditMetric AS m ON m.Code = v.MetricCode) AS s
   ON d.ScorecardId = s.ScorecardId AND d.MetricId = s.MetricId AND d.Code = s.Code
WHEN NOT MATCHED THEN
    INSERT (ScorecardId, MetricId, Code, NameAr, NameEn, GuideAr, SortOrder) VALUES (s.ScorecardId, s.MetricId, s.Code, s.NameAr, s.NameEn, s.GuideAr, s.SortOrder);
UPDATE fin.Scorecard SET Status = 'APPROVED', EffectiveFrom = '2026-10-19'
WHERE Code = 'TRANSPORT_LOGISTICS' AND VersionNo = 1 AND Status = 'DRAFT';
GO
-- AVIATION version 1: Aviation
IF NOT EXISTS (SELECT 1 FROM fin.Scorecard WHERE Code = 'AVIATION' AND VersionNo = 1)
    INSERT fin.Scorecard (Code, VersionNo, NameAr, NameEn, SectorNoteAr, CurrencyId, AmountUnit, MinCoveragePct, QualitativeBoundNotches,
                          SupportMaxAgeMonths, Status, DisclaimerAr, DisclaimerEn)
    SELECT 'AVIATION', 1, N'الطيران', N'Aviation',
           N'شركات الطيران وخدمات الطيران',
           cu.CurrencyId, 1000000, 60, 3, 12, 'DRAFT',
           N'تقييم داخلي يعتمد سلّم موديز (Moody''s) للتصنيف طويل الأجل وطريقة بطاقات التقييم المنشورة: درجة لكل مقياس على خط مستمر ووزن لكل عامل؛ والحدود معايرة بخبرة المحلل للسوق السعودية. ليس تصنيفًا صادرًا عن موديز ولا عن أي وكالة، ولا يحل محل التصنيف الداخلي للبنك.',
           N'An internal assessment on Moody''s long-term rating scale and its published scorecard approach (a score per metric on a linear continuum, a weight per factor); the thresholds are calibrated by expert judgment for the Saudi market. It is not a rating issued by Moody''s or any agency, and it does not replace a bank''s internal rating.'
    FROM ref.Currency AS cu WHERE cu.Code = 'SAR';
MERGE fin.ScorecardMetric AS d
